// runCorporaApply wires all dependencies and runs Phase 3: read legacy
// document_collections rows from Postgres and call
// CorpusService.MigrateCorpus per row. The exit code is 2 when any row
// hit an RPC error so operators can detect a partial run programmatically.
func runCorporaApply(ctx context.Context, cfg *config.Config, legacyOrgID int64, logger *slog.Logger) error {
	tokenSource, err := newTokenSource(ctx, cfg)
	if err != nil {
		return fmt.Errorf("init token source: %w", err)
	}
	if _, err := tokenSource.Token(); err != nil {
