// runDocumentsApply wires all dependencies and runs Phase 4: read legacy
// `documents` rows, stream each file from the legacy filesystem into
// the new MinIO, and call DocumentService.MigrateUpload for each row.
//
// The corpus legacy_id → new UUID map is consumed from a JSON sidecar
// produced by `corpora apply` (default <RUN_DIR>/corpus_map.json). The
// uploaded_by resolution map is left empty for now — every legacy doc
// row is skipped with a deferred-owner note until the user-resolution
// layer ships. Operators see the deferral in the result summary +
// rejection notes; this is by design (see CUTOVER_RUNBOOK.md §4.3).
//
// Exit code 2 when any row hit an error so operators can detect a
// partial run programmatically.
func runDocumentsApply(ctx context.Context, cfg *config.Config, legacyOrgID int64, corpusMapPath string, logger *slog.Logger) error {
	tokenSource, err := newTokenSource(ctx, cfg)
	if err != nil {
		return fmt.Errorf("init token source: %w", err)
	}
	if _, err := tokenSource.Token(); err != nil {
		return fmt.Errorf("fetch initial token: %w", err)
	}

	filesCreds, filesMode, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("build files-svc transport creds: %w", err)
	}
	logger.InfoContext(ctx, "files-svc transport posture", "mode", filesMode.String())
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(filesMode); err != nil {
		return fmt.Errorf("mtls.EnforceMode (files-svc transport creds): %w", err)
	}

	filesClient, err := target.DialFiles(cfg.TargetFilesSvcAddr, mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("dial files-svc: %w", err)
	}
	defer filesClient.Close() //nolint:errcheck
	_ = filesCreds

	pgReader, err := legacy.NewPostgresReader(ctx, cfg.LegacyPostgresDSN)
	if err != nil {
		return fmt.Errorf("dial legacy postgres: %w", err)
	}
	defer pgReader.Close()

	fs := &legacy.LocalFilesystem{Root: cfg.LegacyDocsDir}

	s3Writer, err := legacy.NewS3Writer(ctx, cfg.NewMinIOEndpoint, cfg.NewMinIOAccessKey, cfg.NewMinIOSecretKey)
	if err != nil {
		return fmt.Errorf("init minio writer: %w", err)
	}

	corpusMap, err := readIDMap(corpusMapPath)
	if err != nil {
		return fmt.Errorf("read corpus legacy_id map %s: %w (run `corpora apply` first)", corpusMapPath, err)
	}
	if len(corpusMap) == 0 {
		return fmt.Errorf("corpus legacy_id map %s is empty — run `corpora apply` first", corpusMapPath)
	}

	rejW := openRejectionWriter(ctx, cfg, logger)
	defer func() { _ = rejW.Close() }()

	logger.InfoContext(ctx, "running documents apply",
		"legacy_org_id", legacyOrgID,
		"new_org_id", cfg.OrgID,
		"corpus_map_path", corpusMapPath,
		"corpus_map_size", len(corpusMap),
		"bucket", cfg.NewMinIOBucket,
	)

	out, err := apply.DocumentsApply(ctx, apply.DocumentsApplyInput{
		Reader:            pgReader,
		FS:                fs,
		Object:            s3Writer,
		Client:            filesClient.Document,
		LegacyOrgID:       legacyOrgID,
		OrgID:             cfg.OrgID,
		Bucket:            cfg.NewMinIOBucket,
		CorpusLegacyIDMap: corpusMap,
		// UploadedByMap intentionally empty — see comment above.
		UploadedByMap: nil,
		Writer:        rejW,
	})
	if err != nil {
		return fmt.Errorf("documents apply: %w", err)
	}

	if err := writeIDMap(cfg.RunDir, "document_map.json", out.LegacyIDMap); err != nil {
		return fmt.Errorf("write document_map.json: %w", err)
	}

	logger.InfoContext(ctx, "documents apply complete",
		"read", out.Read,
		"uploaded", out.Uploaded,
		"already_migrated", out.AlreadyMigrated,
		"errors", out.Errors,
		"notes", len(out.Notes),
		"rejection_report", rejectionReportPath(rejW),
	)
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	fmt.Fprintln(os.Stdout, "RESULT:")
	if err := enc.Encode(map[string]any{
		"phase":            "documents",
		"mode":             "apply",
		"read":             out.Read,
		"uploaded":         out.Uploaded,
		"already_migrated": out.AlreadyMigrated,
		"errors":           out.Errors,
		"notes":            len(out.Notes),
	}); err != nil {
		return err
	}
	if out.Errors > 0 {
		os.Exit(2)
	}
	return nil
}

