// runEntitiesApply wires all dependencies and runs Phase 7: read every
// `:Entity` node from legacy Memgraph, resolve its type via the Phase
// 1 sidecar, resolve any corpus refs via the Phase 3 sidecar, and call
// EntityService.MigrateEntity per row. Per-entity failures (type
// unresolved, RPC error) are accumulated as soft errors; the next
// entity still runs. Exit code 2 when any entity hit an error so
// operators can detect a partial run programmatically.
//
// Sidecars consumed:
//   - <RUN_DIR>/entity_type_map.json (required) — Phase 1 output;
//     legacy:entity-type:<orgID>:<name> → new entity_type UUID.
//   - <RUN_DIR>/corpus_map.json (optional in Phase 7 — see
//     legacy.LegacyEntity godoc on why corpus refs are empty here).
//
// Sidecar produced:
//   - <RUN_DIR>/entity_map.json — legacy:entity:<int64> → new entity
//     UUID. Consumed by Phase 8 (edges) and Phase 9 (provenance).
func runEntitiesApply(
	ctx context.Context,
	cfg *config.Config,
	legacyOrgID int,
	typeMapPath, corpusMapPath string,
	logger *slog.Logger,
) error {
	tokenSource, err := newTokenSource(ctx, cfg)
	if err != nil {
		return fmt.Errorf("init token source: %w", err)
	}
	if _, err := tokenSource.Token(); err != nil {
		return fmt.Errorf("fetch initial token: %w", err)
	}

	filesCreds, filesMode, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("build files-svc transport creds: %w", err)
	}
	logger.InfoContext(ctx, "files-svc transport posture", "mode", filesMode.String())
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(filesMode); err != nil {
		return fmt.Errorf("mtls.EnforceMode (files-svc transport creds): %w", err)
	}

	filesClient, err := target.DialFiles(cfg.TargetFilesSvcAddr, mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("dial files-svc: %w", err)
	}
	defer filesClient.Close() //nolint:errcheck
	_ = filesCreds

	memgraphReader, err := legacy.DialMemgraph(ctx,
		cfg.LegacyMemgraphURI,
		cfg.LegacyMemgraphUser,
		cfg.LegacyMemgraphPass,
	)
	if err != nil {
		return fmt.Errorf("dial legacy memgraph: %w", err)
	}
	defer memgraphReader.Close(ctx) //nolint:errcheck

	typeMap, err := readIDMap(typeMapPath)
	if err != nil {
		return fmt.Errorf("read entity_type_map %s: %w (run `entity-types apply` first)", typeMapPath, err)
	}
	if len(typeMap) == 0 {
		return fmt.Errorf("entity_type_map %s is empty — run `entity-types apply` first", typeMapPath)
	}

	// Corpus map is optional for Phase 7 (see EntitiesApplyInput godoc).
	// We still attempt to load it so operators get a clear log message
	// when the file is missing vs malformed.
	var corpusMap map[string]string
	if corpusMapPath != "" {
		if loaded, loadErr := readIDMap(corpusMapPath); loadErr == nil {
			corpusMap = loaded
		} else {
			logger.InfoContext(ctx, "corpus_map not found (optional for Phase 7)",
				"path", corpusMapPath,
				"err", loadErr.Error(),
			)
		}
	}

	rejW := openRejectionWriter(ctx, cfg, logger)
	defer func() { _ = rejW.Close() }()

	logger.InfoContext(ctx, "running entities apply",
		"legacy_org_id", legacyOrgID,
		"new_org_id", cfg.OrgID,
		"type_map_path", typeMapPath,
		"type_map_size", len(typeMap),
		"corpus_map_path", corpusMapPath,
		"corpus_map_size", len(corpusMap),
	)

	out, err := apply.EntitiesApply(ctx, apply.EntitiesApplyInput{
		Reader:      memgraphReader,
		Client:      filesClient.Entity,
		LegacyOrgID: legacyOrgID,
		TypeIDMap:   typeMap,
		CorpusIDMap: corpusMap,
		Writer:      rejW,
	})
	if err != nil {
		return fmt.Errorf("entities apply: %w", err)
	}

	if err := writeIDMap(cfg.RunDir, "entity_map.json", out.LegacyIDMap); err != nil {
		return fmt.Errorf("write entity_map.json: %w", err)
	}

	logger.InfoContext(ctx, "entities apply complete",
		"read", out.Read,
		"migrated", out.Migrated,
		"skipped", out.Skipped,
		"errors", out.Errors,
		"notes", len(out.Notes),
		"rejection_report", rejectionReportPath(rejW),
	)
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	fmt.Fprintln(os.Stdout, "RESULT:")
	if err := enc.Encode(map[string]any{
		"phase":    "entities",
		"mode":     "apply",
		"read":     out.Read,
		"migrated": out.Migrated,
		"skipped":  out.Skipped,
		"errors":   out.Errors,
		"notes":    len(out.Notes),
	}); err != nil {
		return err
	}
	if out.Errors > 0 {
		os.Exit(2)
	}
	return nil
}

// runEdgesApply wires all dependencies and runs Phase 8: read every
// Memgraph relationship between two `:Entity` nodes belonging to
// legacyOrgID, resolve source/target via the Phase 7 sidecar and
// relationship_type via the Phase 2 sidecar, and call
// EdgeService.MigrateEdge per row. Per-edge failures (unresolved
// source/target/type, self-loop, RPC error) are accumulated as soft
// errors / skips; the next edge still runs. Exit code 2 when any edge
// hit an RPC error so operators can detect a partial run
// programmatically.
//
// Sidecars consumed:
//   - <RUN_DIR>/entity_map.json (required) — Phase 7 output;
//     legacy:entity:<int64> → new entity UUID.
//   - <RUN_DIR>/relationship_type_map.json (required) — Phase 2 output;
//     legacy:rel-type:<orgID>:<name> → new relationship_type UUID.
//
// Sidecar produced:
//   - <RUN_DIR>/edge_map.json — legacy:edge:<int64> → new edge UUID.
//     Consumed by Phase 9 (provenance) for edge↔chunk links.
func runEdgesApply(
	ctx context.Context,
	cfg *config.Config,
	legacyOrgID int,
	entityMapPath, relTypeMapPath string,
	logger *slog.Logger,
) error {
	tokenSource, err := newTokenSource(ctx, cfg)
	if err != nil {
		return fmt.Errorf("init token source: %w", err)
	}
	if _, err := tokenSource.Token(); err != nil {
		return fmt.Errorf("fetch initial token: %w", err)
	}

	filesCreds, filesMode, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("build files-svc transport creds: %w", err)
	}
	logger.InfoContext(ctx, "files-svc transport posture", "mode", filesMode.String())
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(filesMode); err != nil {
		return fmt.Errorf("mtls.EnforceMode (files-svc transport creds): %w", err)
	}

	filesClient, err := target.DialFiles(cfg.TargetFilesSvcAddr, mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("dial files-svc: %w", err)
	}
	defer filesClient.Close() //nolint:errcheck
	_ = filesCreds

	memgraphReader, err := legacy.DialMemgraph(ctx,
		cfg.LegacyMemgraphURI,
		cfg.LegacyMemgraphUser,
		cfg.LegacyMemgraphPass,
	)
	if err != nil {
		return fmt.Errorf("dial legacy memgraph: %w", err)
	}
	defer memgraphReader.Close(ctx) //nolint:errcheck

	entityMap, err := readIDMap(entityMapPath)
	if err != nil {
		return fmt.Errorf("read entity_map %s: %w (run `entities apply` first)", entityMapPath, err)
	}
	if len(entityMap) == 0 {
		return fmt.Errorf("entity_map %s is empty — run `entities apply` first", entityMapPath)
	}

	relTypeMap, err := readIDMap(relTypeMapPath)
	if err != nil {
		return fmt.Errorf("read relationship_type_map %s: %w (run `relationship-types apply` first)", relTypeMapPath, err)
	}
	if len(relTypeMap) == 0 {
		return fmt.Errorf("relationship_type_map %s is empty — run `relationship-types apply` first", relTypeMapPath)
	}

	rejW := openRejectionWriter(ctx, cfg, logger)
	defer func() { _ = rejW.Close() }()

	logger.InfoContext(ctx, "running edges apply",
		"legacy_org_id", legacyOrgID,
		"new_org_id", cfg.OrgID,
		"entity_map_path", entityMapPath,
		"entity_map_size", len(entityMap),
		"relationship_type_map_path", relTypeMapPath,
		"relationship_type_map_size", len(relTypeMap),
	)

	out, err := apply.EdgesApply(ctx, apply.EdgesApplyInput{
		Reader:                memgraphReader,
		Client:                filesClient.Edge,
		LegacyOrgID:           legacyOrgID,
		EntityIDMap:           entityMap,
		RelationshipTypeIDMap: relTypeMap,
		Writer:                rejW,
	})
	if err != nil {
		return fmt.Errorf("edges apply: %w", err)
	}

	if err := writeIDMap(cfg.RunDir, "edge_map.json", out.LegacyIDMap); err != nil {
		return fmt.Errorf("write edge_map.json: %w", err)
	}

	logger.InfoContext(ctx, "edges apply complete",
		"read", out.Read,
		"migrated", out.Migrated,
		"skipped", out.Skipped,
		"errors", out.Errors,
		"notes", len(out.Notes),
		"rejection_report", rejectionReportPath(rejW),
	)
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	fmt.Fprintln(os.Stdout, "RESULT:")
	if err := enc.Encode(map[string]any{
		"phase":    "edges",
		"mode":     "apply",
		"read":     out.Read,
		"migrated": out.Migrated,
		"skipped":  out.Skipped,
		"errors":   out.Errors,
		"notes":    len(out.Notes),
	}); err != nil {
		return err
	}
	if out.Errors > 0 {
		os.Exit(2)
	}
	return nil
}

// runProvenanceApply wires all dependencies and runs Phase 9: read
// entity↔chunk + edge↔chunk provenance from legacy Memgraph and
// dispatch them to EntityService.MigrateProvenance and
// EdgeService.MigrateProvenance respectively.
//
// LEGACY GAP: legacy stores entity↔Document provenance only
// (:Entity)-[:MENTIONED_IN]->(:Document) and edges may carry a
// `source_document_id` property — never `source_chunk_id`. The bolt
// readers therefore return empty slices today and the apply layer
// emits a deferred-provenance note for each side. See
// legacy.ProvenanceLink + apply/provenance.go godoc for the full
// rationale and the path to enable real chunk-level provenance.
//
// Sidecars consumed:
//   - <RUN_DIR>/entity_map.json  (Phase 7) — required
//   - <RUN_DIR>/edge_map.json    (Phase 8) — required
//   - <RUN_DIR>/chunk_map.json   (Phase 5) — required
//
// Sidecar produced: none. Provenance is the terminal phase. Exit
// code 2 when any side hit an error so operators can detect a
// partial run programmatically.
func runProvenanceApply(
	ctx context.Context,
	cfg *config.Config,
	legacyOrgID int,
	entityMapPath, edgeMapPath, chunkMapPath string,
	logger *slog.Logger,
) error {
	tokenSource, err := newTokenSource(ctx, cfg)
	if err != nil {
		return fmt.Errorf("init token source: %w", err)
	}
	if _, err := tokenSource.Token(); err != nil {
		return fmt.Errorf("fetch initial token: %w", err)
	}

	filesCreds, filesMode, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("build files-svc transport creds: %w", err)
	}
	logger.InfoContext(ctx, "files-svc transport posture", "mode", filesMode.String())
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(filesMode); err != nil {
