// Command server is the migrator-files CLI entrypoint.
//
// Subcommand structure (per design §8):
//
//	migrator-files <phase> {plan|apply|status|reconcile}
//	migrator-files status                      # all-phase summary
//
// Phases run in fixed dependency order during cutover (per CUTOVER_RUNBOOK.md):
//
//	entity-types apply
//	relationship-types apply
//	corpora apply
//	documents apply
//	chunks apply
//	embeddings apply
//	entities apply
//	edges apply
//	provenance apply
//
// All subcommands honor --org-id from argv (no env equivalent — single-tenant
// cutover is enforced by argv).
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/signal"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"

	"golang.org/x/oauth2"
	"golang.org/x/oauth2/clientcredentials"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator/natskv"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/apply"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/config"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/plan"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/reconcile"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/rejection"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/status"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/target"
)

// openRejectionWriter constructs a JSONL rejection writer for the
// current run. When cfg.RejectionReportDir is empty (rare — there's a
// default in config) we fall back to a NoopWriter so the apply layer
// can call Write unconditionally. Logs the destination path so
// operators can find the file after a run.
func openRejectionWriter(ctx context.Context, cfg *config.Config, logger *slog.Logger) rejection.Writer {
	if cfg.RejectionReportDir == "" {
		logger.InfoContext(ctx, "rejection report disabled (MIGRATOR_REJECTION_REPORT_DIR unset)")
		return rejection.NoopWriter{}
	}
	w, err := rejection.NewFileWriter(cfg.RejectionReportDir)
	if err != nil {
		// Persistence failure must not abort a cutover — log and
		// fall back to discarding notes.
		logger.WarnContext(ctx, "rejection report writer unavailable; falling back to noop",
			"dir", cfg.RejectionReportDir,
			"err", err.Error(),
		)
		return rejection.NoopWriter{}
	}
	logger.InfoContext(ctx, "rejection report writer ready", "path", w.Path())
	return w
}

// rejectionReportPath returns the on-disk path of a *FileWriter, or
// empty string for a NoopWriter / nil. Used to surface the path in
// the per-phase result summary so operators know where to look.
func rejectionReportPath(w rejection.Writer) string {
	if fw, ok := w.(*rejection.FileWriter); ok && fw != nil {
		return fw.Path()
	}
	return ""
}

var phases = []string{
	"entity-types",
	"relationship-types",
	"corpora",
	"documents",
	"chunks",
	"embeddings",
	"entities",
	"edges",
	"provenance",
}

var modes = []string{"plan", "apply", "status", "reconcile"}

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "migrator-files: %v\n", err)
		os.Exit(1)
	}
}

func run(args []string) error {
	if len(args) >= 1 {
		switch args[0] {
		case "-h", "--help", "help":
			printUsage(os.Stdout)
			return nil
		case "status":
			// Top-level status — all-phase summary. Reads sidecars
			// from MIGRATOR_RUN_DIR + NATS-KV cursors. Falls back
			// gracefully to sidecar-only state when NATS isn't
			// reachable.
			cfg, err := config.Load()
			if err != nil {
				return fmt.Errorf("config load: %w", err)
			}
			rest := args[1:]
			orgID := parseFlag(rest, "--org-id")
			if orgID != "" {
				cfg.OrgID = orgID
			}
			if cfg.OrgID == "" {
				return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for status")
			}
			ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
			defer cancel()
			logger := slog.New(slog.NewJSONHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelInfo}))
			logger = logger.With(
				"component", "migrator-files",
				"subcommand", "status",
				"org_id", cfg.OrgID,
			)
			return runStatus(ctx, cfg, logger)
		case "plan":
			// Top-level plan — dry-run row counts across all 9
			// phases. Never calls a new-platform RPC; never writes
			// a sidecar. NATS is intentionally unused (plan doesn't
			// touch cursors).
			cfg, err := config.Load()
			if err != nil {
				return fmt.Errorf("config load: %w", err)
			}
			rest := args[1:]
			orgID := parseFlag(rest, "--org-id")
			if orgID != "" {
				cfg.OrgID = orgID
			}
			legacyOrgIDStr := parseFlag(rest, "--legacy-org-id")
			if cfg.OrgID == "" {
				return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for plan")
			}
			if legacyOrgIDStr == "" {
				return fmt.Errorf("--legacy-org-id <int> is required for plan")
			}
			legacyOrgID, err := strconv.Atoi(legacyOrgIDStr)
			if err != nil {
				return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
			}
			if legacyOrgID <= 0 {
				return fmt.Errorf("--legacy-org-id must be > 0 (got %d)", legacyOrgID)
			}
			ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
			defer cancel()
			logger := slog.New(slog.NewJSONHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelInfo}))
			logger = logger.With(
				"component", "migrator-files",
				"subcommand", "plan",
				"org_id", cfg.OrgID,
			)
			return runPlan(ctx, cfg, int64(legacyOrgID), logger)
		case "reconcile":
			// Top-level reconcile — runs all 9 phases (count parity +
			// deep-spot-check) in a single invocation. There is no
			// per-phase reconcile subcommand; reconcile depends on every
			// sidecar already existing under MIGRATOR_RUN_DIR.
			cfg, err := config.Load()
			if err != nil {
				return fmt.Errorf("config load: %w", err)
			}
			rest := args[1:]
			orgID := parseFlag(rest, "--org-id")
			if orgID != "" {
				cfg.OrgID = orgID
			}
			legacyOrgIDStr := parseFlag(rest, "--legacy-org-id")
			if cfg.OrgID == "" {
				return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for reconcile")
			}
			if legacyOrgIDStr == "" {
				return fmt.Errorf("--legacy-org-id <int> is required for reconcile")
			}
			legacyOrgID, err := strconv.Atoi(legacyOrgIDStr)
			if err != nil {
				return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
			}
			if legacyOrgID <= 0 {
				return fmt.Errorf("--legacy-org-id must be > 0 (got %d)", legacyOrgID)
			}
			ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
			defer cancel()
			logger := slog.New(slog.NewJSONHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelInfo}))
			logger = logger.With(
				"component", "migrator-files",
				"subcommand", "reconcile",
				"org_id", cfg.OrgID,
			)
			return runReconcile(ctx, cfg, legacyOrgID, logger)
		}
	}

	if len(args) < 2 {
		return errUsage()
	}
	subcommand, mode := args[0], args[1]
	if !contains(phases, subcommand) {
		return fmt.Errorf("unknown subcommand %q (valid: %s)", subcommand, strings.Join(phases, ", "))
	}
	if !contains(modes, mode) {
		return fmt.Errorf("unknown mode %q (valid: %s)", mode, strings.Join(modes, ", "))
	}

	// Parse optional flags from the remaining args.
	rest := args[2:]
	orgID := parseFlag(rest, "--org-id")
	legacyOrgIDStr := parseFlag(rest, "--legacy-org-id")

	cfg, err := config.Load()
	if err != nil {
		return fmt.Errorf("config load: %w", err)
	}

	// --org-id argv overrides env.
	if orgID != "" {
		cfg.OrgID = orgID
	}

	ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer cancel()

	logger := slog.New(slog.NewJSONHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelInfo}))
	logger = logger.With(
		"component", "migrator-files",
		"subcommand", subcommand,
		"mode", mode,
		"org_id", cfg.OrgID,
	)

	// Dispatch implemented phases.
	switch {
	case subcommand == "entity-types" && mode == "apply":
		if cfg.LegacyMemgraphURI == "" {
			return fmt.Errorf("LEGACY_MEMGRAPH_URI is required for entity-types apply")
		}
		if cfg.OrgID == "" {
			return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for entity-types apply")
		}
		if legacyOrgIDStr == "" {
			return fmt.Errorf("--legacy-org-id <int> is required for entity-types apply")
		}
		legacyOrgID, err := strconv.Atoi(legacyOrgIDStr)
		if err != nil {
			return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
		}
		return runEntityTypesApply(ctx, cfg, legacyOrgID, logger)
	case subcommand == "relationship-types" && mode == "apply":
		if cfg.LegacyMemgraphURI == "" {
			return fmt.Errorf("LEGACY_MEMGRAPH_URI is required for relationship-types apply")
		}
		if cfg.OrgID == "" {
			return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for relationship-types apply")
		}
		if legacyOrgIDStr == "" {
			return fmt.Errorf("--legacy-org-id <int> is required for relationship-types apply")
		}
		legacyOrgID, err := strconv.Atoi(legacyOrgIDStr)
		if err != nil {
			return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
		}
		return runRelationshipTypesApply(ctx, cfg, legacyOrgID, logger)
	case subcommand == "corpora" && mode == "apply":
		if cfg.LegacyPostgresDSN == "" {
			return fmt.Errorf("LEGACY_POSTGRES_DSN is required for corpora apply")
		}
		if cfg.OrgID == "" {
			return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for corpora apply")
		}
		if legacyOrgIDStr == "" {
			return fmt.Errorf("--legacy-org-id <int> is required for corpora apply")
		}
		legacyOrgID, err := strconv.ParseInt(legacyOrgIDStr, 10, 64)
		if err != nil {
			return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
		}
		if legacyOrgID <= 0 {
			return fmt.Errorf("--legacy-org-id must be > 0 (got %d)", legacyOrgID)
		}
		return runCorporaApply(ctx, cfg, legacyOrgID, logger)
	case subcommand == "documents" && mode == "apply":
		if cfg.LegacyPostgresDSN == "" {
			return fmt.Errorf("LEGACY_POSTGRES_DSN is required for documents apply")
		}
		if cfg.LegacyDocsDir == "" {
			return fmt.Errorf("LEGACY_DOCS_DIR is required for documents apply")
		}
		if cfg.NewMinIOEndpoint == "" {
			return fmt.Errorf("NEW_MINIO_ENDPOINT is required for documents apply")
		}
		if cfg.NewMinIOAccessKey == "" || cfg.NewMinIOSecretKey == "" {
			return fmt.Errorf("NEW_MINIO_ACCESS_KEY and NEW_MINIO_SECRET_KEY are required for documents apply")
		}
		if cfg.NewMinIOBucket == "" {
			return fmt.Errorf("NEW_MINIO_BUCKET is required for documents apply")
		}
		if cfg.OrgID == "" {
			return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for documents apply")
		}
		if legacyOrgIDStr == "" {
			return fmt.Errorf("--legacy-org-id <int> is required for documents apply")
		}
		legacyOrgID, err := strconv.ParseInt(legacyOrgIDStr, 10, 64)
		if err != nil {
			return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
		}
		if legacyOrgID <= 0 {
			return fmt.Errorf("--legacy-org-id must be > 0 (got %d)", legacyOrgID)
		}
		corpusMapPath := parseFlag(rest, "--corpus-legacy-id-map")
		if corpusMapPath == "" {
			corpusMapPath = filepath.Join(cfg.RunDir, "corpus_map.json")
		}
		return runDocumentsApply(ctx, cfg, legacyOrgID, corpusMapPath, logger)
	case subcommand == "entities" && mode == "apply":
		if cfg.LegacyMemgraphURI == "" {
			return fmt.Errorf("LEGACY_MEMGRAPH_URI is required for entities apply")
		}
		if cfg.OrgID == "" {
			return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for entities apply")
		}
		if legacyOrgIDStr == "" {
			return fmt.Errorf("--legacy-org-id <int> is required for entities apply")
		}
		legacyOrgID, err := strconv.Atoi(legacyOrgIDStr)
		if err != nil {
			return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
		}
		if legacyOrgID <= 0 {
			return fmt.Errorf("--legacy-org-id must be > 0 (got %d)", legacyOrgID)
		}
		typeMapPath := parseFlag(rest, "--entity-type-legacy-id-map")
		if typeMapPath == "" {
			typeMapPath = filepath.Join(cfg.RunDir, "entity_type_map.json")
		}
		corpusMapPath := parseFlag(rest, "--corpus-legacy-id-map")
		if corpusMapPath == "" {
			corpusMapPath = filepath.Join(cfg.RunDir, "corpus_map.json")
		}
		return runEntitiesApply(ctx, cfg, legacyOrgID, typeMapPath, corpusMapPath, logger)
	case subcommand == "edges" && mode == "apply":
		if cfg.LegacyMemgraphURI == "" {
			return fmt.Errorf("LEGACY_MEMGRAPH_URI is required for edges apply")
		}
		if cfg.OrgID == "" {
			return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for edges apply")
		}
		if legacyOrgIDStr == "" {
			return fmt.Errorf("--legacy-org-id <int> is required for edges apply")
		}
		legacyOrgID, err := strconv.Atoi(legacyOrgIDStr)
		if err != nil {
			return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
		}
		if legacyOrgID <= 0 {
			return fmt.Errorf("--legacy-org-id must be > 0 (got %d)", legacyOrgID)
		}
		entityMapPath := parseFlag(rest, "--entity-legacy-id-map")
		if entityMapPath == "" {
			entityMapPath = filepath.Join(cfg.RunDir, "entity_map.json")
		}
		relTypeMapPath := parseFlag(rest, "--relationship-type-legacy-id-map")
		if relTypeMapPath == "" {
			relTypeMapPath = filepath.Join(cfg.RunDir, "relationship_type_map.json")
		}
		return runEdgesApply(ctx, cfg, legacyOrgID, entityMapPath, relTypeMapPath, logger)
	case subcommand == "provenance" && mode == "apply":
		if cfg.LegacyMemgraphURI == "" {
			return fmt.Errorf("LEGACY_MEMGRAPH_URI is required for provenance apply")
		}
		if cfg.OrgID == "" {
			return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for provenance apply")
		}
		if legacyOrgIDStr == "" {
			return fmt.Errorf("--legacy-org-id <int> is required for provenance apply")
		}
		legacyOrgID, err := strconv.Atoi(legacyOrgIDStr)
		if err != nil {
			return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
		}
		if legacyOrgID <= 0 {
			return fmt.Errorf("--legacy-org-id must be > 0 (got %d)", legacyOrgID)
		}
		entityMapPath := parseFlag(rest, "--entity-legacy-id-map")
		if entityMapPath == "" {
			entityMapPath = filepath.Join(cfg.RunDir, "entity_map.json")
		}
		edgeMapPath := parseFlag(rest, "--edge-legacy-id-map")
		if edgeMapPath == "" {
			edgeMapPath = filepath.Join(cfg.RunDir, "edge_map.json")
		}
		chunkMapPath := parseFlag(rest, "--chunk-legacy-id-map")
		if chunkMapPath == "" {
			chunkMapPath = filepath.Join(cfg.RunDir, "chunk_map.json")
		}
		return runProvenanceApply(ctx, cfg, legacyOrgID, entityMapPath, edgeMapPath, chunkMapPath, logger)
	case subcommand == "embeddings" && mode == "apply":
		if cfg.LegacyPostgresDSN == "" {
			return fmt.Errorf("LEGACY_POSTGRES_DSN is required for embeddings apply")
		}
		if cfg.LegacyQdrantURL == "" {
			return fmt.Errorf("LEGACY_QDRANT_URL is required for embeddings apply")
		}
		if cfg.OrgID == "" {
			return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for embeddings apply")
		}
		if legacyOrgIDStr == "" {
			return fmt.Errorf("--legacy-org-id <int> is required for embeddings apply")
		}
		legacyOrgID, err := strconv.ParseInt(legacyOrgIDStr, 10, 64)
		if err != nil {
			return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
		}
		if legacyOrgID <= 0 {
			return fmt.Errorf("--legacy-org-id must be > 0 (got %d)", legacyOrgID)
		}
		documentMapPath := parseFlag(rest, "--document-legacy-id-map")
		if documentMapPath == "" {
			documentMapPath = filepath.Join(cfg.RunDir, "document_map.json")
		}
		return runEmbeddingsApply(ctx, cfg, legacyOrgID, documentMapPath, logger)
	case subcommand == "chunks" && mode == "apply":
		if cfg.LegacyPostgresDSN == "" {
			return fmt.Errorf("LEGACY_POSTGRES_DSN is required for chunks apply")
		}
		if cfg.OrgID == "" {
			return fmt.Errorf("--org-id <uuid> (or MIGRATOR_FILES_ORG_ID) is required for chunks apply")
		}
		if legacyOrgIDStr == "" {
			return fmt.Errorf("--legacy-org-id <int> is required for chunks apply")
		}
		legacyOrgID, err := strconv.ParseInt(legacyOrgIDStr, 10, 64)
		if err != nil {
			return fmt.Errorf("--legacy-org-id %q is not a valid integer: %w", legacyOrgIDStr, err)
		}
		if legacyOrgID <= 0 {
			return fmt.Errorf("--legacy-org-id must be > 0 (got %d)", legacyOrgID)
		}
		documentMapPath := parseFlag(rest, "--document-legacy-id-map")
		if documentMapPath == "" {
			documentMapPath = filepath.Join(cfg.RunDir, "document_map.json")
		}
		return runChunksApply(ctx, cfg, legacyOrgID, documentMapPath, logger)
	default:
		logger.InfoContext(ctx, "phase not yet implemented", "phase", subcommand, "mode", mode)
		fmt.Fprintf(os.Stdout, "phase=%s mode=%s not implemented yet\n", subcommand, mode)
		return nil
	}
}

// runEntityTypesApply wires all dependencies and runs Phase 1:
// read distinct entity types from legacy Memgraph and register them
// via EntityTypeService.Bootstrap.
func runEntityTypesApply(ctx context.Context, cfg *config.Config, legacyOrgID int, logger *slog.Logger) error {
	// Service-account token via Keycloak client_credentials grant.
	tokenSource, err := newTokenSource(ctx, cfg)
	if err != nil {
		return fmt.Errorf("init token source: %w", err)
	}
	// Prefetch to validate credentials early before touching Memgraph.
	if _, err := tokenSource.Token(); err != nil {
		return fmt.Errorf("fetch initial token: %w", err)
	}

	// gRPC client to files-svc.
	filesCreds, filesMode, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("build files-svc transport creds: %w", err)
	}
	logger.InfoContext(ctx, "files-svc transport posture", "mode", filesMode.String())
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(filesMode); err != nil {
		return fmt.Errorf("mtls.EnforceMode (files-svc transport creds): %w", err)
	}

	filesClient, err := target.DialFiles(cfg.TargetFilesSvcAddr, mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("dial files-svc: %w", err)
	}
	defer filesClient.Close() //nolint:errcheck
	_ = filesCreds            // posture already logged above

	// Legacy Memgraph reader.
	memgraphReader, err := legacy.DialMemgraph(ctx,
		cfg.LegacyMemgraphURI,
		cfg.LegacyMemgraphUser,
		cfg.LegacyMemgraphPass,
	)
	if err != nil {
		return fmt.Errorf("dial legacy memgraph: %w", err)
	}
	defer memgraphReader.Close(ctx) //nolint:errcheck

	logger.InfoContext(ctx, "running entity-types apply",
		"legacy_org_id", legacyOrgID,
		"new_org_id", cfg.OrgID,
	)

	res, err := apply.EntityTypesApply(ctx, apply.EntityTypesArgs{
		Memgraph:    memgraphReader,
		Client:      filesClient.EntityType,
		LegacyOrgID: legacyOrgID,
		NewOrgID:    cfg.OrgID,
	})
	if err != nil {
		return fmt.Errorf("entity-types apply: %w", err)
	}

	// Write the legacy_id → new_id map to the run dir.
	if err := writeIDMap(cfg.RunDir, "entity_type_map.json", res.IDByLegacyID); err != nil {
		return fmt.Errorf("write entity_type_map.json: %w", err)
	}

	// Print result counts.
	logger.InfoContext(ctx, "entity-types apply complete",
		"source_count", res.SourceCount,
		"bootstrapped", res.Bootstrapped,
	)
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	fmt.Fprintln(os.Stdout, "RESULT:")
	return enc.Encode(map[string]any{
		"phase":        "entity-types",
		"mode":         "apply",
		"source_count": res.SourceCount,
		"bootstrapped": res.Bootstrapped,
	})
}

