}

// runEmbeddingsApply wires all dependencies and runs Phase 6: for each
// (legacy_doc_id, new_doc_uuid) in document_map.json, read every
// legacy `document_chunks` row that has a non-NULL chroma_id (joined
// with its corpus' `vector_collection_name`), pull the matching point
// from legacy Qdrant, then call DocumentService.MigrateChunkEmbeddings
// once per (collection, batch) tuple. The handler writes the vector
// into the new per-org Qdrant collection and updates
// `chunks.embedding_id`. Per Decision 9c: copy verbatim, never
// re-embed.
//
// Per-document and per-batch failures are accumulated as soft errors;
// the next batch / document still runs. Exit code 2 when any batch hit
// an error so operators can detect a partial run programmatically.
func runEmbeddingsApply(ctx context.Context, cfg *config.Config, legacyOrgID int64, documentMapPath string, logger *slog.Logger) error {
	tokenSource, err := newTokenSource(ctx, cfg)
	if err != nil {
		return fmt.Errorf("init token source: %w", err)
	}
	if _, err := tokenSource.Token(); err != nil {
		return fmt.Errorf("fetch initial token: %w", err)
	}

	filesCreds, filesMode, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("build files-svc transport creds: %w", err)
	}
	logger.InfoContext(ctx, "files-svc transport posture", "mode", filesMode.String())
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(filesMode); err != nil {
		return fmt.Errorf("mtls.EnforceMode (files-svc transport creds): %w", err)
	}

	filesClient, err := target.DialFiles(cfg.TargetFilesSvcAddr, mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("dial files-svc: %w", err)
	}
	defer filesClient.Close() //nolint:errcheck
	_ = filesCreds

	pgReader, err := legacy.NewPostgresReader(ctx, cfg.LegacyPostgresDSN)
	if err != nil {
		return fmt.Errorf("dial legacy postgres: %w", err)
	}
	defer pgReader.Close()

	qdrantReader, err := legacy.NewQdrantReader(ctx, cfg.LegacyQdrantURL)
	if err != nil {
		return fmt.Errorf("dial legacy qdrant: %w", err)
	}
	defer qdrantReader.Close() //nolint:errcheck

	documentMap, err := readIDMap(documentMapPath)
	if err != nil {
		return fmt.Errorf("read document legacy_id map %s: %w (run `documents apply` first)", documentMapPath, err)
	}
	if len(documentMap) == 0 {
		return fmt.Errorf("document legacy_id map %s is empty — run `documents apply` first", documentMapPath)
	}

	rejW := openRejectionWriter(ctx, cfg, logger)
	defer func() { _ = rejW.Close() }()

	logger.InfoContext(ctx, "running embeddings apply",
		"legacy_org_id", legacyOrgID,
		"new_org_id", cfg.OrgID,
		"document_map_path", documentMapPath,
		"document_map_size", len(documentMap),
	)

	out, err := apply.EmbeddingsApply(ctx, apply.EmbeddingsApplyInput{
		PG:                  pgReader,
		Qdrant:              qdrantReader,
		Client:              filesClient.Document,
		LegacyOrgID:         legacyOrgID,
		DocumentLegacyIDMap: documentMap,
		Writer:              rejW,
	})
	if err != nil {
		return fmt.Errorf("embeddings apply: %w", err)
	}

	logger.InfoContext(ctx, "embeddings apply complete",
		"documents_processed", out.DocumentsProcessed,
		"chunks_read", out.ChunksRead,
		"points_fetched", out.PointsFetched,
		"embeddings_written", out.EmbeddingsWritten,
		"errors", out.Errors,
		"notes", len(out.Notes),
		"rejection_report", rejectionReportPath(rejW),
	)
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	fmt.Fprintln(os.Stdout, "RESULT:")
	if err := enc.Encode(map[string]any{
		"phase":               "embeddings",
		"mode":                "apply",
		"documents_processed": out.DocumentsProcessed,
		"chunks_read":         out.ChunksRead,
		"points_fetched":      out.PointsFetched,
		"embeddings_written":  out.EmbeddingsWritten,
		"errors":              out.Errors,
		"notes":               len(out.Notes),
	}); err != nil {
		return err
	}
	if out.Errors > 0 {
		os.Exit(2)
	}
	return nil
}

// runEntitiesApply wires all dependencies and runs Phase 7: read every
// `:Entity` node from legacy Memgraph, resolve its type via the Phase
// 1 sidecar, resolve any corpus refs via the Phase 3 sidecar, and call
// EntityService.MigrateEntity per row. Per-entity failures (type
// unresolved, RPC error) are accumulated as soft errors; the next
// entity still runs. Exit code 2 when any entity hit an error so
// operators can detect a partial run programmatically.
//
// Sidecars consumed:
//   - <RUN_DIR>/entity_type_map.json (required) — Phase 1 output;
//     legacy:entity-type:<orgID>:<name> → new entity_type UUID.
//   - <RUN_DIR>/corpus_map.json (optional in Phase 7 — see
//     legacy.LegacyEntity godoc on why corpus refs are empty here).
