// runProvenanceApply wires all dependencies and runs Phase 9: read
// entity↔chunk + edge↔chunk provenance from legacy Memgraph and
// dispatch them to EntityService.MigrateProvenance and
// EdgeService.MigrateProvenance respectively.
//
// LEGACY GAP: legacy stores entity↔Document provenance only
// (:Entity)-[:MENTIONED_IN]->(:Document) and edges may carry a
// `source_document_id` property — never `source_chunk_id`. The bolt
// readers therefore return empty slices today and the apply layer
// emits a deferred-provenance note for each side. See
// legacy.ProvenanceLink + apply/provenance.go godoc for the full
// rationale and the path to enable real chunk-level provenance.
//
// Sidecars consumed:
//   - <RUN_DIR>/entity_map.json  (Phase 7) — required
//   - <RUN_DIR>/edge_map.json    (Phase 8) — required
//   - <RUN_DIR>/chunk_map.json   (Phase 5) — required
//
// Sidecar produced: none. Provenance is the terminal phase. Exit
// code 2 when any side hit an error so operators can detect a
// partial run programmatically.
func runProvenanceApply(
	ctx context.Context,
	cfg *config.Config,
	legacyOrgID int,
	entityMapPath, edgeMapPath, chunkMapPath string,
	logger *slog.Logger,
) error {
	tokenSource, err := newTokenSource(ctx, cfg)
	if err != nil {
		return fmt.Errorf("init token source: %w", err)
