// runReconcile dials all legacy + files-svc connections, loads
// every sidecar from MIGRATOR_RUN_DIR, runs reconcile.Reconcile across
// all 9 phases, writes the JSON report to <RUN_DIR>/<run-id>/reconcile.json,
// prints a one-line summary per phase to stdout, and exits non-zero
// when any phase has mismatches.
//
// Sidecars consumed (all under <RUN_DIR>):
//   - entity_type_map.json        Phase 1
//   - relationship_type_map.json  Phase 2
//   - corpus_map.json             Phase 3
//   - document_map.json           Phase 4
//   - chunk_map.json              Phase 5
//   - entity_map.json             Phase 7
//   - edge_map.json               Phase 8
//
// Phases 6 (embeddings) and 9 (provenance) have no sidecar by design;
// reconcile reports them with an explanatory note rather than failing
// the run on a missing file.
//
// Exit code: 0 when report.Mismatches == 0; 2 otherwise.
func runReconcile(ctx context.Context, cfg *config.Config, legacyOrgID int, logger *slog.Logger) error {
	if cfg.LegacyMemgraphURI == "" {
		return fmt.Errorf("LEGACY_MEMGRAPH_URI is required for reconcile")
	}
	if cfg.LegacyPostgresDSN == "" {
		return fmt.Errorf("LEGACY_POSTGRES_DSN is required for reconcile")
	}
	if cfg.RunDir == "" {
		return fmt.Errorf("MIGRATOR_RUN_DIR is required for reconcile")
	}

	tokenSource, err := newTokenSource(ctx, cfg)
	if err != nil {
		return fmt.Errorf("init token source: %w", err)
	}
	if _, err := tokenSource.Token(); err != nil {
		return fmt.Errorf("fetch initial token: %w", err)
	}

	filesCreds, filesMode, err := mtls.BuildTransportCredentials(mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("build files-svc transport creds: %w", err)
	}
	logger.InfoContext(ctx, "files-svc transport posture", "mode", filesMode.String())
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(filesMode); err != nil {
		return fmt.Errorf("mtls.EnforceMode (files-svc transport creds): %w", err)
	}

	filesClient, err := target.DialFiles(cfg.TargetFilesSvcAddr, mtls.Config{
		CertFile:   cfg.MTLSCertFile,
		KeyFile:    cfg.MTLSKeyFile,
		CAFile:     cfg.MTLSCAFile,
		ServerName: cfg.MTLSFilesSvcServerName,
	})
	if err != nil {
		return fmt.Errorf("dial files-svc: %w", err)
	}
	defer filesClient.Close() //nolint:errcheck
	_ = filesCreds

	memgraphReader, err := legacy.DialMemgraph(ctx, cfg.LegacyMemgraphURI, cfg.LegacyMemgraphUser, cfg.LegacyMemgraphPass)
	if err != nil {
		return fmt.Errorf("dial legacy memgraph: %w", err)
	}
	defer memgraphReader.Close(ctx) //nolint:errcheck

	pgReader, err := legacy.NewPostgresReader(ctx, cfg.LegacyPostgresDSN)
	if err != nil {
		return fmt.Errorf("dial legacy postgres: %w", err)
	}
	defer pgReader.Close()

	// Load every sidecar — missing files are tolerated for
	// Phase-6/9 (which never emit one) but treated as warnings for
	// the others. We never fail the run on missing files; an empty
	// sidecar simply produces a 0 vs N parity check that flags the
	// gap clearly to the operator.
	sidecars := reconcile.Sidecars{
		EntityType:       readSidecarOrEmpty(cfg.RunDir, "entity_type_map.json", logger),
		RelationshipType: readSidecarOrEmpty(cfg.RunDir, "relationship_type_map.json", logger),
		Corpus:           readSidecarOrEmpty(cfg.RunDir, "corpus_map.json", logger),
		Document:         readSidecarOrEmpty(cfg.RunDir, "document_map.json", logger),
		Chunk:            readSidecarOrEmpty(cfg.RunDir, "chunk_map.json", logger),
		Entity:           readSidecarOrEmpty(cfg.RunDir, "entity_map.json", logger),
		Edge:             readSidecarOrEmpty(cfg.RunDir, "edge_map.json", logger),
	}

	logger.InfoContext(ctx, "running reconcile",
		"legacy_org_id", legacyOrgID,
		"new_org_id", cfg.OrgID,
		"run_dir", cfg.RunDir,
		"entity_type_sidecar", len(sidecars.EntityType),
		"relationship_type_sidecar", len(sidecars.RelationshipType),
		"corpus_sidecar", len(sidecars.Corpus),
		"document_sidecar", len(sidecars.Document),
		"chunk_sidecar", len(sidecars.Chunk),
		"entity_sidecar", len(sidecars.Entity),
		"edge_sidecar", len(sidecars.Edge),
	)

	report, err := reconcile.Reconcile(ctx, reconcile.Input{
		LegacyMemgraph: memgraphReader,
		LegacyCorpus:   pgReader,
		LegacyDocument: pgReader,
		LegacyChunks:   pgReader,
		Clients: reconcile.Clients{
			EntityType:       filesClient.EntityType,
			RelationshipType: filesClient.RelationshipType,
			Corpus:           filesClient.Corpus,
			Document:         filesClient.Document,
			Entity:           filesClient.Entity,
			Edge:             filesClient.Edge,
		},
		Sidecars:    sidecars,
		LegacyOrgID: legacyOrgID,
		OrgID:       cfg.OrgID,
		SampleSize:  reconcile.DefaultSampleSize,
	})
	if err != nil {
		return fmt.Errorf("reconcile: %w", err)
	}

	// Persist the report to <RUN_DIR>/<run-id>/reconcile.json so
	// re-runs don't clobber prior reports.
	reportDir := filepath.Join(cfg.RunDir, report.RunID)
	if err := os.MkdirAll(reportDir, 0o750); err != nil {
		return fmt.Errorf("mkdir %s: %w", reportDir, err)
	}
	reportPath := filepath.Join(reportDir, "reconcile.json")
	rf, err := os.Create(reportPath)
	if err != nil {
		return fmt.Errorf("create %s: %w", reportPath, err)
	}
	{
		enc := json.NewEncoder(rf)
		enc.SetIndent("", "  ")
		if err := enc.Encode(report); err != nil {
			_ = rf.Close()
			return fmt.Errorf("encode reconcile report: %w", err)
		}
	}
	_ = rf.Close()

	// Print one-line summary per phase. Order matches the apply
	// dependency chain so the operator scans top-to-bottom.
	phaseOrder := []string{
		"entity-types", "relationship-types", "corpora", "documents",
		"chunks", "embeddings", "entities", "edges", "provenance",
	}
	fmt.Fprintln(os.Stdout, "RECONCILE:")
	for _, name := range phaseOrder {
		pr, ok := report.Phases[name]
		if !ok {
			continue
		}
		status := "OK"
		if !pr.CountParityOK || pr.SampleMismatches > 0 || pr.SampleErrors > 0 {
			status = "FAIL"
		}
		fmt.Fprintf(os.Stdout,
			"  %-20s %s  legacy=%d  new=%d  sidecar=%d  sampled=%d  mismatches=%d  errors=%d\n",
			name, status, pr.LegacyCount, pr.NewCount, pr.SidecarCount, pr.SampleSize, pr.SampleMismatches, pr.SampleErrors,
		)
	}
	fmt.Fprintf(os.Stdout, "report: %s\n", reportPath)

	logger.InfoContext(ctx, "reconcile complete",
		"run_id", report.RunID,
		"mismatches", report.Mismatches,
		"report_path", reportPath,
	)
	if report.Mismatches > 0 {
		os.Exit(2)
	}
	return nil
}

// runStatus implements the read-only status mode of migrator-files.
// It joins per-phase JSON sidecars from MIGRATOR_RUN_DIR with the
// NATS-KV cursor bucket and prints a fixed-width per-phase table:
//
//	PHASE              COUNT  STATE              LAST_RUN
//	entity-types       42     migrated           2026-05-08T10:14:23Z
//	embeddings         0      no-sidecar         —
//	   note: embeddings have no sidecar by design …
//
// When NATS isn't reachable the status command degrades gracefully:
// it prints a top-of-output WARNING line, then renders the sidecar-
// only state for every phase. There is no hard failure on NATS down
// because the operator might be running status mid-incident with the
// bucket temporarily unavailable.
//
// LAST_RUN is sourced from the sidecar file mtime (cursor values are
// just integer offsets, no timestamp). Phases without a sidecar
// (embeddings, provenance) carry an explanatory Note rather than a
// misleading "pending" state.
func runStatus(ctx context.Context, cfg *config.Config, logger *slog.Logger) error {
	if cfg.RunDir == "" {
		return fmt.Errorf("MIGRATOR_RUN_DIR is required for status")
	}

	in := status.Input{
		OrgID:  cfg.OrgID,
		RunDir: cfg.RunDir,
		Bucket: cfg.NATSKVBucketPrefix,
	}

	// Try to open the cursor bucket. Failure here is downgraded to a
	// warning — status MUST work without NATS so operators can audit
	// sidecar state during a NATS outage.
	if cfg.NATSURL != "" {
		kvBackend, nc, err := natskv.Open(ctx, cfg.NATSURL, cfg.NATSCredsFile, cfg.NATSCAFile, cfg.NATSKVBucketPrefix)
		if err != nil {
			logger.WarnContext(ctx, "nats kv unavailable; status will fall back to sidecar-only state",
				"err", err.Error(),
			)
			in.CursorErr = err
		} else {
			defer nc.Close()
			in.Cursor = migrator.NewCursor(kvBackend)
			logger.InfoContext(ctx, "cursor bucket opened", "bucket", cfg.NATSKVBucketPrefix)
		}
	} else {
		in.CursorErr = errors.New("NATS_URL is empty")
	}

	rep, err := status.Summarize(ctx, in)
	if err != nil {
		return fmt.Errorf("status summarize: %w", err)
	}

	// Print human-readable table to stdout, then a STATUS-prefixed
	// JSON line for machine consumption (mirrors migrator-org's
	// printStatus convention).
	if err := status.Render(rep, os.Stdout); err != nil {
		return fmt.Errorf("status render: %w", err)
	}
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	fmt.Fprintln(os.Stdout, "STATUS:")
	if err := enc.Encode(rep); err != nil {
		return fmt.Errorf("status encode: %w", err)
	}

	logger.InfoContext(ctx, "status complete",
		"org_id", rep.OrgID,
		"run_dir", rep.RunDir,
		"phases_reported", len(rep.Phases),
		"cursor_ok", rep.CursorOK,
	)
	return nil
}

// runPlan implements the dry-run plan mode. For each of the 9 phases
// it counts the legacy rows that would be migrated without making any
// new-platform RPC and without writing any sidecar. NATS is
// intentionally unused — plan doesn't touch cursors. Validates DSNs
// up-front so operators see a clean error message instead of a deep
// per-phase note.
func runPlan(ctx context.Context, cfg *config.Config, legacyOrgID int64, logger *slog.Logger) error {
	if cfg.LegacyMemgraphURI == "" {
		return fmt.Errorf("LEGACY_MEMGRAPH_URI is required for plan")
	}
	if cfg.LegacyPostgresDSN == "" {
		return fmt.Errorf("LEGACY_POSTGRES_DSN is required for plan")
	}

	memgraphReader, err := legacy.DialMemgraph(ctx,
		cfg.LegacyMemgraphURI,
		cfg.LegacyMemgraphUser,
		cfg.LegacyMemgraphPass,
	)
	if err != nil {
		return fmt.Errorf("dial legacy memgraph: %w", err)
	}
	defer memgraphReader.Close(ctx) //nolint:errcheck

	pgReader, err := legacy.NewPostgresReader(ctx, cfg.LegacyPostgresDSN)
	if err != nil {
		return fmt.Errorf("dial legacy postgres: %w", err)
	}
	defer pgReader.Close()

	logger.InfoContext(ctx, "running plan",
		"legacy_org_id", legacyOrgID,
		"new_org_id", cfg.OrgID,
	)

	rep, err := plan.Run(ctx, plan.Input{
		Memgraph:    memgraphReader,
		Postgres:    pgReader,
		LegacyOrgID: legacyOrgID,
		OrgID:       cfg.OrgID,
	})
	if err != nil {
		return fmt.Errorf("plan run: %w", err)
	}

	if err := plan.Render(rep, os.Stdout); err != nil {
		return fmt.Errorf("plan render: %w", err)
	}
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	fmt.Fprintln(os.Stdout, "PLAN:")
	if err := enc.Encode(rep); err != nil {
		return fmt.Errorf("plan encode: %w", err)
	}

	logger.InfoContext(ctx, "plan complete",
		"phases_reported", len(rep.Phases),
	)
	return nil
}

// readSidecarOrEmpty reads a JSON sidecar from runDir/filename and
// returns an empty (non-nil) map when the file does not exist or is
// unreadable. Reconcile tolerates missing sidecars — they show up as
// a 0 vs N parity gap which is exactly what the operator wants to
// see when a phase didn't run.
func readSidecarOrEmpty(runDir, filename string, logger *slog.Logger) map[string]string {
	path := filepath.Join(runDir, filename)
	m, err := readIDMap(path)
	if err != nil {
		logger.Info("sidecar missing or unreadable; treating as empty", "path", path, "err", err)
		return map[string]string{}
	}
	if m == nil {
		return map[string]string{}
	}
	return m
}

// readIDMap reads a map[string]string previously written by writeIDMap
// from disk. Used by Phase 4+ to resume the legacy-id translation chain
// without re-running upstream phases in the same process.
func readIDMap(path string) (map[string]string, error) {
	f, err := os.Open(path) //nolint:gosec // path comes from operator-controlled config
	if err != nil {
		return nil, err
	}
	defer f.Close() //nolint:errcheck
	var m map[string]string
	if err := json.NewDecoder(f).Decode(&m); err != nil {
		return nil, fmt.Errorf("decode %s: %w", path, err)
	}
	return m, nil
}

// writeIDMap writes a map[string]string to <runDir>/entity_type_map.json,
// creating runDir if it does not exist.
func writeIDMap(runDir, filename string, m map[string]string) error {
	if err := os.MkdirAll(runDir, 0o750); err != nil {
		return fmt.Errorf("mkdir %s: %w", runDir, err)
	}
	path := filepath.Join(runDir, filename)
	f, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("create %s: %w", path, err)
	}
	defer f.Close() //nolint:errcheck
	enc := json.NewEncoder(f)
	enc.SetIndent("", "  ")
	if err := enc.Encode(m); err != nil {
		return fmt.Errorf("encode %s: %w", path, err)
	}
	return nil
}

// newTokenSource builds an oauth2.TokenSource from clientcredentials
// against the configured Keycloak realm. Uses the optional internal
// OIDC URL (in-network) when set, falling back to the public issuer URL.
func newTokenSource(ctx context.Context, cfg *config.Config) (oauth2.TokenSource, error) {
	issuer := cfg.OIDCIssuerURL
	if cfg.OIDCInternalURL != "" {
		issuer = cfg.OIDCInternalURL
	}
	cc := &clientcredentials.Config{
		ClientID:     cfg.KeycloakClientID,
		ClientSecret: cfg.KeycloakClientSecret,
		TokenURL:     strings.TrimRight(issuer, "/") + "/protocol/openid-connect/token",
	}
	return cc.TokenSource(ctx), nil
}

// parseFlag extracts the value for a --flag <value> argument from args.
// Returns empty string if the flag is absent.
func parseFlag(args []string, flag string) string {
	for i := 0; i+1 < len(args); i++ {
		if args[i] == flag {
			return args[i+1]
		}
	}
	return ""
}

func contains(haystack []string, needle string) bool {
	for _, s := range haystack {
		if s == needle {
			return true
		}
	}
	return false
}

func errUsage() error {
	var sb strings.Builder
	printUsage(&sb)
	return fmt.Errorf("usage error\n%s", sb.String())
}

